create table if not exists public.sales_charge_catalog_v610 (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, code text not null, name text not null, charge_kind text not null default 'other', service_variant_id uuid not null references public.product_variants(id), default_quantity numeric not null default 1, auto_apply_dine_in boolean not null default false, auto_apply_takeaway boolean not null default false, auto_apply_delivery boolean not null default false, active boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,code));;
